<?php $title=$mode==='create'?'New News Post':'Edit News Post';$heading=$title;$subheading='Images may be selected from static assets or uploaded here.';ob_start(); ?><div class="panel form-panel"><form method="post" enctype="multipart/form-data" class="stack-form" action="<?= $mode==='create'?'/admin/news/new':'/admin/news/'.e($post['id']).'/edit' ?>"><?= csrf_field() ?><label>Title<input name="Title" required maxlength="160" value="<?= e($post['Title']??'') ?>"></label><label>Slug<input name="Slug" maxlength="180" value="<?= e($post['Slug']??'') ?>" placeholder="auto-generated-from-title"></label><label>Excerpt<textarea name="Excerpt" rows="2" maxlength="255"><?= e($post['Excerpt']??'') ?></textarea></label><label>Body<textarea name="Body" rows="14" required><?= e($post['Body']??'') ?></textarea></label><label>Existing image path<input name="Image" value="<?= e($post['Image']??'') ?>" placeholder="static/uploads/banner.png"></label><label>Or upload image<input type="file" name="image_upload" accept="image/png,image/jpeg,image/gif,image/webp,image/svg+xml"></label><div class="check-row"><label><input type="checkbox" name="Published" value="1" <?= !isset($post['Published'])||(int)$post['Published']===1?'checked':'' ?>> Published</label><label><input type="checkbox" name="Pinned" value="1" <?= (int)($post['Pinned']??0)===1?'checked':'' ?>> Pinned</label></div><div class="form-actions"><a class="btn btn-ghost" href="/admin/news">Cancel</a><button class="btn btn-gold">Save Post</button></div></form></div><?php $content=ob_get_clean();require __DIR__.'/../../layouts/admin.php'; ?>
